-- MathLabs V11 — Student Experience + Curriculum Engine + 6.º básico
begin;

update public.courses
set curriculum_version='Bases Curriculares vigentes',
    curriculum_source_url='https://www.curriculumnacional.cl/curriculum/1o-6o-basico/matematica/6-basico',
    description='Matemática 6.º básico · currículo completo V1 de MathLabs.',
    is_available=true,is_published=true,updated_at=now()
where id='cl-6-basico';

on conflict (id) do update set course_id=excluded.course_id,slug=excluded.slug,name=excluded.name,description=excluded.description,icon=excluded.icon,sort_order=excluded.sort_order,is_published=true;

on conflict (id) do update set axis_id=excluded.axis_id,code=excluded.code,title=excluded.title,summary=excluded.summary,official_source_url=excluded.official_source_url,sort_order=excluded.sort_order,is_published=true;

on conflict (id) do update set course_id=excluded.course_id,axis_id=excluded.axis_id,slug=excluded.slug,title=excluded.title,summary=excluded.summary,difficulty=excluded.difficulty,estimated_minutes=excluded.estimated_minutes,sort_order=excluded.sort_order,content_status='published',is_published=true,updated_at=now();

on conflict (objective_id,topic_id) do update set weight=excluded.weight;

on conflict (topic_id,prerequisite_topic_id) do update set relation_type=excluded.relation_type;


on conflict (id) do update set unit_id=excluded.unit_id,slug=excluded.slug,title=excluded.title,summary=excluded.summary,objective=excluded.objective,estimated_minutes=excluded.estimated_minutes,difficulty=excluded.difficulty,sort_order=excluded.sort_order,is_published=true,prerequisites=excluded.prerequisites,tags=excluded.tags,question_filter=excluded.question_filter,updated_at=now();

on conflict (lesson_id,objective_id) do update set topic_id=excluded.topic_id,alignment_type=excluded.alignment_type;

delete from public.lesson_blocks where lesson_id in ('school-6b-oa01a','school-6b-oa01b','school-6b-oa01c','school-6b-oa02','school-6b-oa03a','school-6b-oa03b','school-6b-oa04a','school-6b-oa04b','school-6b-oa05a','school-6b-oa05b','school-6b-oa06a','school-6b-oa06b','school-6b-oa07a','school-6b-oa07b','school-6b-oa08','school-6b-oa09a','school-6b-oa09b','school-6b-oa10a','school-6b-oa10b','school-6b-oa11a','school-6b-oa11b','school-6b-oa12a','school-6b-oa12b','school-6b-oa13','school-6b-oa14','school-6b-oa15','school-6b-oa16','school-6b-oa17','school-6b-oa20','school-6b-oa21','school-6b-oa18','school-6b-oa19','school-6b-oa22a','school-6b-oa22b','school-6b-oa23','school-6b-oa24');

on conflict (code) do update set course_id=excluded.course_id,topic_id=excluded.topic_id,prompt=excluded.prompt,options=excluded.options,correct_option=excluded.correct_option,explanation=excluded.explanation,feedback_by_option=excluded.feedback_by_option,difficulty=excluded.difficulty,skill=excluded.skill,sort_order=excluded.sort_order,is_published=true,updated_at=now();

on conflict (code) do update set course_id=excluded.course_id,topic_id=excluded.topic_id,prompt=excluded.prompt,options=excluded.options,correct_option=excluded.correct_option,explanation=excluded.explanation,option_feedback=excluded.option_feedback,difficulty=excluded.difficulty,diagnostic_version=excluded.diagnostic_version,sort_order=excluded.sort_order,is_published=true,updated_at=now();

on conflict (id) do update set course_id=excluded.course_id,slug=excluded.slug,title=excluded.title,description=excluded.description,icon=excluded.icon,sort_order=excluded.sort_order,is_published=true,updated_at=now();

on conflict (code) do update set review_set_id=excluded.review_set_id,prompt=excluded.prompt,options=excluded.options,correct_option=excluded.correct_option,explanation=excluded.explanation,feedback_by_option=excluded.feedback_by_option,difficulty=excluded.difficulty,skill=excluded.skill,sort_order=excluded.sort_order,is_published=true,updated_at=now();


create table if not exists public.visual_lab_catalog (
  slug text primary key,
  course_id text not null references public.courses(id) on delete cascade,
  title text not null,
  topic_id text references public.knowledge_topics(id) on delete set null,
  sort_order integer not null default 0,
  is_published boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
alter table public.visual_lab_catalog enable row level security;
drop policy if exists "Published visual lab catalog is readable" on public.visual_lab_catalog;
create policy "Published visual lab catalog is readable" on public.visual_lab_catalog for select to anon,authenticated using(is_published=true);
grant select on public.visual_lab_catalog to anon,authenticated;
on conflict (slug) do update set course_id=excluded.course_id,title=excluded.title,topic_id=excluded.topic_id,sort_order=excluded.sort_order,is_published=true,updated_at=now();

alter table public.student_visual_lab_progress drop constraint if exists student_visual_lab_progress_slug_check;
alter table public.student_visual_lab_progress add constraint student_visual_lab_progress_slug_check check (lab_slug in ('valor-posicional','multiplicacion-visual','division-grupos','medidas-conversion','decimales-cuadricula','patrones-maquina','muro-fracciones','datos-en-accion','factores-primos','mezclador-razones','porcentaje-100','fracciones-mixtas','escala-decimal','balanza-ecuaciones','explorador-angulos','constructor-volumen','simulador-probabilidad','graficos-comparativos'));


create or replace function public.record_visual_lab_result(p_lab_slug text,p_score integer)
returns jsonb language plpgsql security definer set search_path=''
as $$
declare v_user uuid:=auth.uid();v_score integer;v_attempts integer;v_last integer;v_best integer;v_completed boolean;
begin
 if v_user is null then raise exception 'Debes iniciar sesión'; end if;
 if not exists(select 1 from public.visual_lab_catalog where slug=p_lab_slug and is_published) then raise exception 'Laboratorio no disponible'; end if;
 v_score:=greatest(0,least(100,coalesce(p_score,0)));
 values(v_user,p_lab_slug,1,v_score,v_score,v_score>=70,case when v_score>=70 then now() else null end,now())
 on conflict(user_id,lab_slug) do update set attempts=public.student_visual_lab_progress.attempts+1,last_score=excluded.last_score,
 best_score=greatest(public.student_visual_lab_progress.best_score,excluded.best_score),completed=public.student_visual_lab_progress.completed or excluded.completed,
 last_completed_at=case when excluded.completed then now() else public.student_visual_lab_progress.last_completed_at end,updated_at=now()
 returning attempts,last_score,best_score,completed into v_attempts,v_last,v_best,v_completed;
 return jsonb_build_object('lab_slug',p_lab_slug,'attempts',v_attempts,'last_score',v_last,'best_score',v_best,'completed',v_completed);
end $$;
revoke all on function public.record_visual_lab_result(text,integer) from public,anon;
grant execute on function public.record_visual_lab_result(text,integer) to authenticated;

create or replace function public.get_school_diagnostic_info(p_course_id text)
returns jsonb language plpgsql security definer set search_path=''
as $$
declare v_version text;v_total integer;
begin
 if auth.uid() is null then raise exception 'Debes iniciar sesión'; end if;
 if not exists(select 1 from public.courses where id=p_course_id and is_published and is_available) then raise exception 'Curso no disponible'; end if;
 select diagnostic_version into v_version from public.school_diagnostic_items where course_id=p_course_id and is_published group by diagnostic_version order by max(updated_at) desc,diagnostic_version desc limit 1;
 select count(*)::integer into v_total from public.school_diagnostic_items where course_id=p_course_id and diagnostic_version=v_version and is_published;
 return jsonb_build_object('course_id',p_course_id,'diagnostic_version',v_version,'total_questions',coalesce(v_total,0),'available',coalesce(v_total,0)>=8);
end $$;
revoke all on function public.get_school_diagnostic_info(text) from public,anon;
grant execute on function public.get_school_diagnostic_info(text) to authenticated;

create or replace function public.start_school_diagnostic(p_course_id text default 'cl-5-basico')
returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pg_temp
as $$
declare v_user uuid:=auth.uid();v_session uuid;v_total integer;v_version text;
begin
 if v_user is null then raise exception 'Debes iniciar sesión'; end if;
 if not exists(select 1 from public.courses where id=p_course_id and is_published and is_available) then raise exception 'Curso no válido'; end if;
 select diagnostic_version into v_version from public.school_diagnostic_items
 where course_id=p_course_id and is_published
 group by diagnostic_version order by max(updated_at) desc,diagnostic_version desc limit 1;
 if v_version is null then raise exception 'Este curso no tiene diagnóstico publicado'; end if;
 update public.school_diagnostic_sessions set status='abandoned',updated_at=now() where user_id=v_user and course_id=p_course_id and status='started';
 select count(*) into v_total from public.school_diagnostic_items where course_id=p_course_id and diagnostic_version=v_version and is_published;
 if v_total<8 then raise exception 'Diagnóstico incompleto'; end if;
 values(v_user,p_course_id,'started',v_total,0,'{}'::jsonb,v_version,0,0,now(),now()) returning id into v_session;
 select v_session,id,row_number() over(order by sort_order,code)::integer from public.school_diagnostic_items
 where course_id=p_course_id and diagnostic_version=v_version and is_published order by sort_order,code;
 return jsonb_build_object('session_id',v_session,'course_id',p_course_id,'total_questions',v_total,'diagnostic_version',v_version);
end $$;
revoke all on function public.start_school_diagnostic(text) from public,anon,authenticated;
grant execute on function public.start_school_diagnostic(text) to authenticated;

create or replace function public.configure_my_learning_profile(p_course_id text,p_preferred_session_minutes integer default 20,p_focus_mode text default 'balanced')
returns jsonb language plpgsql security definer set search_path=''
as $$
declare v_user uuid:=auth.uid();v_course record;v_minutes integer;v_mode text;
begin
 if v_user is null then raise exception 'Debes iniciar sesión'; end if;
 select id,slug,name into v_course from public.courses where id=p_course_id and is_available and is_published;
 if not found then raise exception 'Curso no disponible'; end if;
 v_minutes:=case when p_preferred_session_minutes in(10,15,20,30,45) then p_preferred_session_minutes else 20 end;
 v_mode:=case when p_focus_mode in('balanced','reinforcement','challenge') then p_focus_mode else 'balanced' end;
 update public.student_course_enrollments set is_primary=false,updated_at=now() where user_id=v_user and is_primary;
 on conflict(user_id,course_id) do update set is_primary=true,status='active',updated_at=now();
 values(v_user,null,p_course_id,'follow_course','student',now(),now())
 on conflict(user_id) do update set course_id=excluded.course_id,updated_at=now();
 values(v_user,4,v_minutes,v_mode,now())
 on conflict(user_id) do update set preferred_session_minutes=excluded.preferred_session_minutes,focus_mode=excluded.focus_mode,updated_at=now();
 return jsonb_build_object('course_id',v_course.id,'course_slug',v_course.slug,'course_name',v_course.name,'preferred_session_minutes',v_minutes,'focus_mode',v_mode);
end $$;
revoke all on function public.configure_my_learning_profile(text,integer,text) from public,anon;
grant execute on function public.configure_my_learning_profile(text,integer,text) to authenticated;

create or replace function public.get_my_learning_hub(p_course_id text default null)
returns jsonb language plpgsql security definer set search_path=''
as $$
declare v_user uuid:=auth.uid();v_course_id text;v_course record;v_pref record;v_summary jsonb;v_axes jsonb;v_topics jsonb;v_actions jsonb;v_recent jsonb;
begin
 if v_user is null then raise exception 'Debes iniciar sesión'; end if;
 v_course_id:=p_course_id;
 if v_course_id is null then select course_id into v_course_id from public.student_course_enrollments where user_id=v_user and status='active' order by is_primary desc,enrolled_at desc limit 1; end if;
 if v_course_id is null then select course_id into v_course_id from public.student_school_profiles where user_id=v_user; end if;
 if v_course_id is null then raise exception 'Configura primero tu curso'; end if;
 select id,slug,name,short_name into v_course from public.courses where id=v_course_id and is_published and is_available;
 if not found then raise exception 'Curso no disponible'; end if;
 select weekly_goal,preferred_session_minutes,focus_mode into v_pref from public.student_learning_preferences where user_id=v_user;

 select jsonb_build_object(
  'mastery_percent',coalesce(round(avg(coalesce(m.mastery_percent,0))),0)::integer,
  'mastered_topics',count(*) filter(where coalesce(m.mastery_percent,0)>=80)::integer,
  'total_topics',count(*)::integer,
  'lessons_completed',(select count(*)::integer from public.lesson_progress lp join public.lessons l on l.id=lp.lesson_id where lp.user_id=v_user and lp.status='completed' and exists(select 1 from public.lesson_curriculum_links lc join public.knowledge_topics kt on kt.id=lc.topic_id where lc.lesson_id=l.id and kt.course_id=v_course_id)),
  'practice_sessions',(select count(*)::integer from public.school_practice_sessions where user_id=v_user and course_id=v_course_id and status='completed'),
  'practice_accuracy',coalesce((select round(100.0*count(*) filter(where r.is_correct)/nullif(count(*),0))::integer from public.school_practice_responses r join public.school_practice_sessions s on s.id=r.session_id where r.user_id=v_user and s.course_id=v_course_id),0),
  'questions_answered',(select count(*)::integer from public.school_practice_responses r join public.school_practice_sessions s on s.id=r.session_id where r.user_id=v_user and s.course_id=v_course_id),
  'labs_completed',(select count(*)::integer from public.student_visual_lab_progress p join public.visual_lab_catalog c on c.slug=p.lab_slug where p.user_id=v_user and p.completed and c.course_id=v_course_id),
  'labs_total',(select count(*)::integer from public.visual_lab_catalog where course_id=v_course_id and is_published),
  'reviews_completed',(select count(*)::integer from public.school_review_sessions s join public.school_review_sets r on r.id=s.review_set_id where s.user_id=v_user and s.status='completed' and r.course_id=v_course_id),
  'latest_diagnostic_score',(select score_percent from public.school_diagnostic_sessions where user_id=v_user and course_id=v_course_id and status='completed' order by completed_at desc nulls last limit 1),
  'activities_this_week',(
    (select count(*) from public.school_practice_sessions where user_id=v_user and course_id=v_course_id and status='completed' and completed_at>=date_trunc('week',now()))
    +(select count(*) from public.lesson_progress lp join public.lessons l on l.id=lp.lesson_id where lp.user_id=v_user and lp.status='completed' and exists(select 1 from public.lesson_curriculum_links lc join public.knowledge_topics kt on kt.id=lc.topic_id where lc.lesson_id=l.id and kt.course_id=v_course_id) and lp.completed_at>=date_trunc('week',now()))
    +(select count(*) from public.student_visual_lab_progress p join public.visual_lab_catalog c on c.slug=p.lab_slug where p.user_id=v_user and p.completed and c.course_id=v_course_id and p.last_completed_at>=date_trunc('week',now()))
  )::integer
 ) into v_summary
 from public.knowledge_topics t left join public.student_topic_mastery m on m.topic_id=t.id and m.user_id=v_user
 where t.course_id=v_course_id and t.is_published;

 select coalesce(jsonb_agg(jsonb_build_object('axis_id',x.id,'axis_name',x.name,'axis_icon',x.icon,'mastery_percent',x.mastery,'mastered_topics',x.mastered,'total_topics',x.total) order by x.sort_order),'[]'::jsonb)
 into v_axes from(
  select a.id,a.name,a.icon,a.sort_order,coalesce(round(avg(coalesce(m.mastery_percent,0))),0)::integer mastery,
  count(*) filter(where coalesce(m.mastery_percent,0)>=80)::integer mastered,count(*)::integer total
  from public.curriculum_axes a join public.knowledge_topics t on t.axis_id=a.id and t.course_id=v_course_id and t.is_published
  left join public.student_topic_mastery m on m.topic_id=t.id and m.user_id=v_user
  where a.course_id=v_course_id and a.is_published group by a.id,a.name,a.icon,a.sort_order
 )x;

 select coalesce(jsonb_agg(jsonb_build_object('topic_id',x.id,'topic_slug',x.slug,'topic_title',x.title,'axis_name',x.axis_name,'mastery_percent',x.mastery,'status',x.status,'reason',x.reason,'priority',1,'lesson_slug',x.lesson_slug) order by x.mastery,x.sort_order),'[]'::jsonb)
 into v_topics from(
  select t.id,t.slug,t.title,a.name axis_name,coalesce(m.mastery_percent,0)::integer mastery,coalesce(m.status,'not_started') status,t.sort_order,
  case when coalesce(m.mastery_percent,0)=0 then 'Tema aún sin evidencia suficiente.' when coalesce(m.mastery_percent,0)<50 then 'Conviene reforzar este tema.' when coalesce(m.mastery_percent,0)<80 then 'Está en desarrollo.' else 'Buen dominio.' end reason,
  (select l.slug from public.lesson_curriculum_links lc join public.lessons l on l.id=lc.lesson_id where lc.topic_id=t.id and l.is_published order by l.sort_order limit 1) lesson_slug
  from public.knowledge_topics t join public.curriculum_axes a on a.id=t.axis_id
  left join public.student_topic_mastery m on m.topic_id=t.id and m.user_id=v_user
  where t.course_id=v_course_id and t.is_published and (v_pref.focus_mode='challenge' or coalesce(m.mastery_percent,0)<80)
  order by case when v_pref.focus_mode='challenge' then coalesce(m.mastery_percent,0) end desc nulls last,
           case when v_pref.focus_mode<>'challenge' then coalesce(m.mastery_percent,0) end asc nulls last,t.sort_order limit 8
 )x;

 with c as(
  select 120 priority,'diagnostic'::text action_type,'Realiza tu diagnóstico' title,'Construye un punto de partida para personalizar tu ruta.' description,'/diagnostico-escolar' href,'🧭' emoji
  where not exists(select 1 from public.school_diagnostic_sessions where user_id=v_user and course_id=v_course_id and status='completed')
  union all
  select 100,'practice','Practica '||t.title,case when coalesce(m.mastery_percent,0)<50 then 'Es una de tus brechas principales.' else 'Una práctica puede consolidar este tema.' end,'/practica-escolar/'||t.slug,'✏️'
  from public.knowledge_topics t left join public.student_topic_mastery m on m.topic_id=t.id and m.user_id=v_user
  where t.course_id=v_course_id and t.is_published and coalesce(m.mastery_percent,0)<80
  union all
  select 82,'lab','Laboratorio · '||lab.title,'Manipula el modelo y completa una exploración.','/laboratorio/'||v_course.slug||'/'||lab.slug,'🧪'
  from lateral (select c.slug,c.title from public.visual_lab_catalog c where c.course_id=v_course_id and c.is_published and not exists(select 1 from public.student_visual_lab_progress p where p.user_id=v_user and p.lab_slug=c.slug and p.completed) order by c.sort_order,c.slug limit 1) lab
  union all
  select 75,'review','Desafío · '||r.title,'Comprueba si los aprendizajes de esta unidad están firmes.','/repaso-escolar/'||r.slug,'🏁'
  from public.school_review_sets r where r.course_id=v_course_id and r.is_published and not exists(select 1 from public.school_review_sessions s where s.user_id=v_user and s.review_set_id=r.id and s.status='completed' and s.score_percent>=70)
 )
 select coalesce(jsonb_agg(jsonb_build_object('action_type',action_type,'title',title,'description',description,'href',href,'emoji',emoji,'priority',priority) order by priority desc),'[]'::jsonb)
 into v_actions from(select * from c order by priority desc limit 6)x;

 with a as(
  select 'practice'::text kind,'Práctica · '||t.title title,s.score_percent::integer score,s.completed_at happened_at from public.school_practice_sessions s join public.knowledge_topics t on t.id=s.topic_id where s.user_id=v_user and s.course_id=v_course_id and s.status='completed'
  union all select 'review','Repaso · '||r.title,s.score_percent::integer,s.completed_at from public.school_review_sessions s join public.school_review_sets r on r.id=s.review_set_id where s.user_id=v_user and s.status='completed' and r.course_id=v_course_id
  union all select 'diagnostic','Diagnóstico · '||v_course.short_name,s.score_percent::integer,s.completed_at from public.school_diagnostic_sessions s where s.user_id=v_user and s.course_id=v_course_id and s.status='completed'
  union all select 'lesson','Lección · '||l.title,lp.best_quiz_score,lp.completed_at from public.lesson_progress lp join public.lessons l on l.id=lp.lesson_id where lp.user_id=v_user and lp.status='completed' and exists(select 1 from public.lesson_curriculum_links lc join public.knowledge_topics kt on kt.id=lc.topic_id where lc.lesson_id=l.id and kt.course_id=v_course_id)
  union all select 'lab','Laboratorio · '||c.title,p.best_score,p.last_completed_at from public.student_visual_lab_progress p join public.visual_lab_catalog c on c.slug=p.lab_slug where p.user_id=v_user and p.completed and c.course_id=v_course_id
 )
 select coalesce(jsonb_agg(jsonb_build_object('kind',kind,'title',title,'score',score,'happened_at',happened_at) order by happened_at desc),'[]'::jsonb)
 into v_recent from(select * from a where happened_at is not null order by happened_at desc limit 8)x;

 return jsonb_build_object(
  'course',jsonb_build_object('id',v_course.id,'slug',v_course.slug,'name',v_course.name,'short_name',v_course.short_name),
  'preferences',jsonb_build_object('weekly_goal',v_pref.weekly_goal,'preferred_session_minutes',v_pref.preferred_session_minutes,'focus_mode',v_pref.focus_mode),
  'summary',v_summary,'axes',v_axes,'priority_topics',v_topics,'next_actions',v_actions,'recent_activity',v_recent
 );
end $$;
revoke all on function public.get_my_learning_hub(text) from public,anon;
grant execute on function public.get_my_learning_hub(text) to authenticated;

create table if not exists public.student_learning_sessions(
 id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,
 course_id text not null references public.courses(id) on delete cascade,target_minutes integer not null check(target_minutes in(10,15,20,30,45)),
 status text not null default 'active' check(status in('active','ready_to_complete','completed','abandoned')),
 started_at timestamptz not null default now(),completed_at timestamptz,updated_at timestamptz not null default now()
);
create table if not exists public.student_learning_session_items(
 session_id uuid not null references public.student_learning_sessions(id) on delete cascade,position integer not null,
 action_type text not null check(action_type in('lesson','practice','review','lab','diagnostic')),title text not null,description text not null default '',
 href text not null,reference_key text,emoji text not null default '✓',estimated_minutes integer not null default 5 check(estimated_minutes between 1 and 45),
 status text not null default 'pending' check(status in('pending','current','completed','skipped')),completed_at timestamptz,primary key(session_id,position)
);
alter table public.student_learning_session_items add column if not exists reference_key text;
create index if not exists student_learning_sessions_user_status_idx on public.student_learning_sessions(user_id,status,updated_at desc);
alter table public.student_learning_sessions enable row level security;
alter table public.student_learning_session_items enable row level security;
drop policy if exists "Users read own learning sessions" on public.student_learning_sessions;
create policy "Users read own learning sessions" on public.student_learning_sessions for select to authenticated using(user_id=auth.uid());
drop policy if exists "Users read own learning session items" on public.student_learning_session_items;
create policy "Users read own learning session items" on public.student_learning_session_items for select to authenticated using(exists(select 1 from public.student_learning_sessions s where s.id=session_id and s.user_id=auth.uid()));
revoke all on table public.student_learning_sessions from anon;
revoke all on table public.student_learning_session_items from anon;
revoke insert,update,delete on table public.student_learning_sessions from authenticated;
revoke insert,update,delete on table public.student_learning_session_items from authenticated;
grant select on table public.student_learning_sessions to authenticated;
grant select on table public.student_learning_session_items to authenticated;

create or replace function public.get_my_active_learning_session()
returns jsonb language plpgsql security definer set search_path=''
as $$
declare v_user uuid:=auth.uid();v_s record;
begin
 if v_user is null then raise exception 'Debes iniciar sesión'; end if;
 select s.id,s.course_id,s.target_minutes,s.status,s.started_at,c.slug course_slug,c.name course_name into v_s
 from public.student_learning_sessions s join public.courses c on c.id=s.course_id
 where s.user_id=v_user and s.status in('active','ready_to_complete') order by s.updated_at desc limit 1;
 if not found then return null; end if;
 return jsonb_build_object('id',v_s.id,'course_id',v_s.course_id,'course_slug',v_s.course_slug,'course_name',v_s.course_name,'target_minutes',v_s.target_minutes,'status',v_s.status,'started_at',v_s.started_at,
 'items',coalesce((select jsonb_agg(jsonb_build_object('position',i.position,'action_type',i.action_type,'title',i.title,'description',i.description,'href',i.href,'reference_key',i.reference_key,'emoji',i.emoji,'estimated_minutes',i.estimated_minutes,'status',i.status,'completed_at',i.completed_at) order by i.position) from public.student_learning_session_items i where i.session_id=v_s.id),'[]'::jsonb));
end $$;

create or replace function public.start_my_learning_session(p_course_id text default null,p_target_minutes integer default null)
returns jsonb language plpgsql security definer set search_path=''
as $$
declare v_user uuid:=auth.uid();v_existing jsonb;v_course text;v_pref integer;v_minutes integer;v_hub jsonb;v_action jsonb;v_session uuid;v_pos integer:=0;v_used integer:=0;v_duration integer;v_type text;
begin
 if v_user is null then raise exception 'Debes iniciar sesión'; end if;
 v_existing:=public.get_my_active_learning_session(); if v_existing is not null then return v_existing; end if;
 v_course:=p_course_id;
 if v_course is null then select course_id into v_course from public.student_course_enrollments where user_id=v_user and status='active' order by is_primary desc,enrolled_at desc limit 1; end if;
 if v_course is null then select course_id into v_course from public.student_school_profiles where user_id=v_user; end if;
 if v_course is null then raise exception 'Configura primero tu curso'; end if;
 select preferred_session_minutes into v_pref from public.student_learning_preferences where user_id=v_user;
 v_minutes:=coalesce(p_target_minutes,v_pref,20); if v_minutes not in(10,15,20,30,45) then v_minutes:=20; end if;
 v_hub:=public.get_my_learning_hub(v_course);
 for v_action in select value from jsonb_array_elements(coalesce(v_hub->'next_actions','[]'::jsonb)) loop
   v_type:=coalesce(v_action->>'action_type','practice');
   v_duration:=case v_type when 'diagnostic' then least(15,v_minutes) when 'practice' then 7 when 'lab' then 7 when 'review' then 10 when 'lesson' then 8 else 5 end;
   if v_pos>0 and v_used+v_duration>v_minutes+2 then continue; end if;
   v_pos:=v_pos+1;
   values(v_session,v_pos,v_type,coalesce(v_action->>'title','Actividad'),coalesce(v_action->>'description',''),coalesce(v_action->>'href','/hoy'),coalesce(v_action->>'emoji','✓'),v_duration,case when v_pos=1 then 'current' else 'pending' end);
   v_used:=v_used+v_duration; if v_pos>=4 then exit; end if;
 end loop;
 if v_pos=0 then insert into public.student_learning_session_items(session_id,position,action_type,title,description,href,emoji,estimated_minutes,status)
 values(v_session,1,'lab','Explora libremente','Elige un laboratorio o tema para fortalecer.','/laboratorio/'||(v_hub->'course'->>'slug'),'🧪',least(10,v_minutes),'current'); end if;
 return public.get_my_active_learning_session();
end $$;

create or replace function public.update_my_learning_session_item(p_session_id uuid,p_position integer,p_status text)
returns jsonb language plpgsql security definer set search_path=''
as $$
declare v_user uuid:=auth.uid();v_next integer;v_remaining integer;
begin
 if v_user is null then raise exception 'Debes iniciar sesión'; end if;
 if p_status not in('completed','skipped') then raise exception 'Estado no válido'; end if;
 if not exists(select 1 from public.student_learning_sessions where id=p_session_id and user_id=v_user and status in('active','ready_to_complete')) then raise exception 'Sesión no encontrada'; end if;
 update public.student_learning_session_items set status=p_status,completed_at=case when p_status='completed' then now() else null end where session_id=p_session_id and position=p_position and status='current';
 if not found then raise exception 'Actividad no disponible'; end if;
 select min(position) into v_next from public.student_learning_session_items where session_id=p_session_id and status='pending';
 if v_next is not null then update public.student_learning_session_items set status='current' where session_id=p_session_id and position=v_next; end if;
 select count(*) into v_remaining from public.student_learning_session_items where session_id=p_session_id and status in('pending','current');
 update public.student_learning_sessions set status=case when v_remaining=0 then 'ready_to_complete' else 'active' end,updated_at=now() where id=p_session_id;
 return public.get_my_active_learning_session();
end $$;

create or replace function public.complete_my_learning_session(p_session_id uuid)
returns jsonb language plpgsql security definer set search_path=''
as $$
declare v_user uuid:=auth.uid();v_done integer;v_skip integer;
begin
 if v_user is null then raise exception 'Debes iniciar sesión'; end if;
 if exists(select 1 from public.student_learning_session_items where session_id=p_session_id and status in('pending','current')) then raise exception 'Aún quedan actividades pendientes'; end if;
 update public.student_learning_sessions set status='completed',completed_at=coalesce(completed_at,now()),updated_at=now() where id=p_session_id and user_id=v_user and status='ready_to_complete';
 if not found then raise exception 'Sesión no disponible para completar'; end if;
 select count(*) filter(where status='completed'),count(*) filter(where status='skipped') into v_done,v_skip from public.student_learning_session_items where session_id=p_session_id;
 return jsonb_build_object('session_id',p_session_id,'completed',true,'activities_completed',v_done,'activities_skipped',v_skip);
end $$;

revoke all on function public.get_my_active_learning_session() from public,anon;
revoke all on function public.start_my_learning_session(text,integer) from public,anon;
revoke all on function public.update_my_learning_session_item(uuid,integer,text) from public,anon;
revoke all on function public.complete_my_learning_session(uuid) from public,anon;
grant execute on function public.get_my_active_learning_session() to authenticated;
grant execute on function public.start_my_learning_session(text,integer) to authenticated;
grant execute on function public.update_my_learning_session_item(uuid,integer,text) to authenticated;
grant execute on function public.complete_my_learning_session(uuid) to authenticated;


-- ----------------------------------------------------------
-- G. Tendencia de aprendizaje genérica por curso
-- ----------------------------------------------------------
create or replace function public.get_my_learning_trend(
  p_course_id text default 'cl-5-basico',
  p_weeks integer default 8
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user uuid := auth.uid();
  v_weeks integer := greatest(2, least(16, coalesce(p_weeks, 8)));
begin
  if v_user is null then
    raise exception 'Debes iniciar sesión';
  end if;

  return (
    with weeks as (
      select generate_series(
        date_trunc('week', now()) - ((v_weeks - 1) * interval '1 week'),
        date_trunc('week', now()),
        interval '1 week'
      ) as week_start
    ),
    practice as (
      select
        date_trunc('week', completed_at) as week_start,
        count(*)::integer as sessions,
        round(avg(score_percent))::integer as avg_score
      from public.school_practice_sessions
      where user_id = v_user
        and course_id = p_course_id
        and status = 'completed'
        and completed_at >= date_trunc('week', now()) - ((v_weeks - 1) * interval '1 week')
      group by 1
    ),
    questions as (
      select
        date_trunc('week', r.answered_at) as week_start,
        count(*)::integer as questions
      from public.school_practice_responses r
      join public.school_practice_sessions s on s.id = r.session_id
      where r.user_id = v_user
        and s.course_id = p_course_id
        and r.answered_at >= date_trunc('week', now()) - ((v_weeks - 1) * interval '1 week')
      group by 1
    ),
    lesson_activity as (
      select
        date_trunc('week', lp.completed_at) as week_start,
        count(*)::integer as lessons
      from public.lesson_progress lp
      join public.lessons l on l.id = lp.lesson_id
      where lp.user_id = v_user
        and lp.status = 'completed'
        and l.question_filter->>'course_id' = p_course_id
        and lp.completed_at >= date_trunc('week', now()) - ((v_weeks - 1) * interval '1 week')
      group by 1
    ),
    lab_activity as (
      select
        date_trunc('week', p.last_completed_at) as week_start,
        count(*)::integer as labs
      from public.student_visual_lab_progress p
      join public.visual_lab_catalog c on c.slug = p.lab_slug
      where p.user_id = v_user
        and p.completed
        and c.course_id = p_course_id
        and p.last_completed_at >= date_trunc('week', now()) - ((v_weeks - 1) * interval '1 week')
      group by 1
    )
    select jsonb_agg(
      jsonb_build_object(
        'week_start', w.week_start,
        'practice_sessions', coalesce(p.sessions, 0),
        'average_score', coalesce(p.avg_score, 0),
        'questions_answered', coalesce(q.questions, 0),
        'lessons_completed', coalesce(l.lessons, 0),
        'labs_completed', coalesce(lb.labs, 0)
      )
      order by w.week_start
    )
    from weeks w
    left join practice p using (week_start)
    left join questions q using (week_start)
    left join lesson_activity l using (week_start)
    left join lab_activity lb using (week_start)
  );
end;
$$;
revoke all on function public.get_my_learning_trend(text,integer) from public,anon;
grant execute on function public.get_my_learning_trend(text,integer) to authenticated;


commit;
