insert into public.curriculum_axes (id,course_id,slug,name,description,icon,sort_order,is_published) values
('ma06-num','cl-6-basico','numeros-y-operaciones','Números y operaciones','Factores, operaciones, razones, porcentajes, fracciones y decimales.','123',1,true),
('ma06-alg','cl-6-basico','patrones-y-algebra','Patrones y álgebra','Tablas, reglas, expresiones con letras y ecuaciones.','x',2,true),
('ma06-geo','cl-6-basico','geometria','Geometría','Triángulos, teselaciones y relaciones entre ángulos.','△',3,true),
('ma06-med','cl-6-basico','medicion','Medición','Superficie, volumen y medición de ángulos.','∠',4,true),
('ma06-datos','cl-6-basico','datos-y-probabilidades','Datos y probabilidades','Distribuciones, experimentos aleatorios y gráficos.','▥',5,true)
insert into public.curriculum_objectives (id,course_id,axis_id,code,title,summary,official_source_url,sort_order,is_published) values
('ma06-oa-01','cl-6-basico','ma06-num','MA06 OA 01','Factores, múltiplos, primos y compuestos','Comprender factores y múltiplos de números naturales menores de 100, reconocer primos y compuestos y resolver problemas con múltiplos.','https://www.curriculumnacional.cl/curriculum/1o-6o-basico/matematica/6-basico',1,true),
('ma06-oa-02','cl-6-basico','ma06-num','MA06 OA 02','Cuatro operaciones en resolución de problemas','Realizar cálculos con las cuatro operaciones en problemas y usar calculadora cuando corresponda.','https://www.curriculumnacional.cl/curriculum/1o-6o-basico/matematica/6-basico',2,true),
('ma06-oa-03','cl-6-basico','ma06-num','MA06 OA 03','Razones','Comprender la razón de forma concreta, pictórica y simbólica.','https://www.curriculumnacional.cl/curriculum/1o-6o-basico/matematica/6-basico',3,true),
('ma06-oa-04','cl-6-basico','ma06-num','MA06 OA 04','Porcentajes','Comprender el porcentaje mediante representaciones concretas, pictóricas y simbólicas.','https://www.curriculumnacional.cl/curriculum/1o-6o-basico/matematica/6-basico',4,true),
('ma06-oa-05','cl-6-basico','ma06-num','MA06 OA 05','Fracciones impropias y números mixtos','Establecer equivalencias entre fracciones impropias y números mixtos y representarlos en la recta numérica.','https://www.curriculumnacional.cl/curriculum/1o-6o-basico/matematica/6-basico',5,true),
('ma06-oa-06','cl-6-basico','ma06-num','MA06 OA 06','Adición y sustracción de fracciones y números mixtos','Resolver adiciones y sustracciones de fracciones propias, impropias y números mixtos.','https://www.curriculumnacional.cl/curriculum/1o-6o-basico/matematica/6-basico',6,true),
('ma06-oa-07','cl-6-basico','ma06-num','MA06 OA 07','Multiplicación y división de decimales','Comprender la multiplicación y división de decimales por naturales, múltiplos de 10 y decimales hasta la milésima.','https://www.curriculumnacional.cl/curriculum/1o-6o-basico/matematica/6-basico',7,true),
('ma06-oa-08','cl-6-basico','ma06-num','MA06 OA 08','Problemas con fracciones y decimales','Resolver problemas rutinarios y no rutinarios que involucren fracciones, números mixtos y decimales.','https://www.curriculumnacional.cl/curriculum/1o-6o-basico/matematica/6-basico',8,true),
('ma06-oa-09','cl-6-basico','ma06-alg','MA06 OA 09','Relaciones en tablas y reglas','Identificar patrones entre valores de una tabla y formular reglas con lenguaje matemático.','https://www.curriculumnacional.cl/curriculum/1o-6o-basico/matematica/6-basico',9,true),
('ma06-oa-10','cl-6-basico','ma06-alg','MA06 OA 10','Generalizaciones con letras y ecuaciones','Representar relaciones entre números naturales usando expresiones con letras y ecuaciones.','https://www.curriculumnacional.cl/curriculum/1o-6o-basico/matematica/6-basico',10,true),
('ma06-oa-11','cl-6-basico','ma06-alg','MA06 OA 11','Ecuaciones de primer grado','Resolver ecuaciones de primer grado con una incógnita usando modelos y procedimientos formales.','https://www.curriculumnacional.cl/curriculum/1o-6o-basico/matematica/6-basico',11,true),
('ma06-oa-12','cl-6-basico','ma06-geo','MA06 OA 12','Construcción y comparación de triángulos','Construir y comparar triángulos según lados y ángulos usando instrumentos o software geométrico.','https://www.curriculumnacional.cl/curriculum/1o-6o-basico/matematica/6-basico',12,true),
('ma06-oa-13','cl-6-basico','ma06-geo','MA06 OA 13','Área de redes de cubos y paralelepípedos','Comprender el área de superficies de cubos y paralelepípedos a partir de sus redes.','https://www.curriculumnacional.cl/curriculum/1o-6o-basico/matematica/6-basico',13,true),
('ma06-oa-14','cl-6-basico','ma06-geo','MA06 OA 14','Teselaciones y transformaciones','Realizar teselaciones con figuras 2D usando traslaciones, reflexiones y rotaciones.','https://www.curriculumnacional.cl/curriculum/1o-6o-basico/matematica/6-basico',14,true),
('ma06-oa-15','cl-6-basico','ma06-geo','MA06 OA 15','Construcción de ángulos','Construir ángulos agudos, obtusos, rectos, extendidos y completos.','https://www.curriculumnacional.cl/curriculum/1o-6o-basico/matematica/6-basico',15,true),
('ma06-oa-16','cl-6-basico','ma06-geo','MA06 OA 16','Relaciones entre ángulos','Identificar relaciones entre ángulos formados por rectas que se cortan.','https://www.curriculumnacional.cl/curriculum/1o-6o-basico/matematica/6-basico',16,true),
('ma06-oa-17','cl-6-basico','ma06-geo','MA06 OA 17','Suma de ángulos interiores','Comprender que los ángulos interiores de un triángulo suman 180° y los de un cuadrilátero 360°.','https://www.curriculumnacional.cl/curriculum/1o-6o-basico/matematica/6-basico',17,true),
('ma06-oa-18','cl-6-basico','ma06-med','MA06 OA 18','Superficie de cubos y paralelepípedos','Calcular superficie de cubos y paralelepípedos en unidades cuadradas.','https://www.curriculumnacional.cl/curriculum/1o-6o-basico/matematica/6-basico',18,true),
('ma06-oa-19','cl-6-basico','ma06-med','MA06 OA 19','Volumen de cubos y paralelepípedos','Calcular volumen de cubos y paralelepípedos en unidades cúbicas.','https://www.curriculumnacional.cl/curriculum/1o-6o-basico/matematica/6-basico',19,true),
('ma06-oa-20','cl-6-basico','ma06-med','MA06 OA 20','Estimación y medición de ángulos','Estimar y medir ángulos con transportador y expresar la medida en grados.','https://www.curriculumnacional.cl/curriculum/1o-6o-basico/matematica/6-basico',20,true),
('ma06-oa-21','cl-6-basico','ma06-med','MA06 OA 21','Ángulos en paralelas y triángulos','Calcular ángulos en rectas paralelas cortadas por una transversal y en triángulos.','https://www.curriculumnacional.cl/curriculum/1o-6o-basico/matematica/6-basico',21,true),
('ma06-oa-22','cl-6-basico','ma06-datos','MA06 OA 22','Comparación de distribuciones','Comparar distribuciones de dos grupos mediante diagramas de puntos y de tallo y hojas.','https://www.curriculumnacional.cl/curriculum/1o-6o-basico/matematica/6-basico',22,true),
('ma06-oa-23','cl-6-basico','ma06-datos','MA06 OA 23','Tendencia en experimentos aleatorios','Conjeturar tendencias al repetir experimentos con dados, monedas u otros dispositivos aleatorios.','https://www.curriculumnacional.cl/curriculum/1o-6o-basico/matematica/6-basico',23,true),
('ma06-oa-24','cl-6-basico','ma06-datos','MA06 OA 24','Gráficos de barra doble y circulares','Leer e interpretar gráficos de barra doble y circulares y comunicar conclusiones.','https://www.curriculumnacional.cl/curriculum/1o-6o-basico/matematica/6-basico',24,true)
insert into public.knowledge_topics (id,course_id,axis_id,slug,title,summary,difficulty,estimated_minutes,sort_order,content_status,is_published) values
('topic-ma06-oa01a','cl-6-basico','ma06-num','factores-y-divisores','Factores y divisores','Encuentra todos los factores de un número y explica la relación con la división exacta.','Fundamental',35,1,'published',true),
('topic-ma06-oa01b','cl-6-basico','ma06-num','multiplos-mcm','Múltiplos y encuentros periódicos','Genera múltiplos y resuelve situaciones donde dos ciclos vuelven a coincidir.','Fundamental',35,2,'published',true),
('topic-ma06-oa01c','cl-6-basico','ma06-num','primos-y-compuestos','Números primos y compuestos','Distingue números primos y compuestos mediante sus factores.','Fundamental',35,3,'published',true),
('topic-ma06-oa02','cl-6-basico','ma06-num','cuatro-operaciones-problemas','Problemas con las cuatro operaciones','Elige operaciones, estima y comprueba resultados en problemas de varias etapas.','Fundamental',35,4,'published',true),
('topic-ma06-oa03a','cl-6-basico','ma06-num','razon-comparacion','Razón como comparación','Interpreta una razón como comparación multiplicativa entre dos cantidades.','Fundamental',35,5,'published',true),
('topic-ma06-oa03b','cl-6-basico','ma06-num','razones-equivalentes','Razones equivalentes','Construye y reconoce razones equivalentes usando tablas y diagramas.','Fundamental',35,6,'published',true),
('topic-ma06-oa04a','cl-6-basico','ma06-num','porcentaje-significado','Porcentaje como parte de 100','Representa porcentajes en cuadrículas, fracciones y decimales.','Fundamental',35,7,'published',true),
('topic-ma06-oa04b','cl-6-basico','ma06-num','porcentaje-de-una-cantidad','Porcentaje de una cantidad','Calcula porcentajes frecuentes y resuelve problemas cotidianos.','Fundamental',35,8,'published',true),
('topic-ma06-oa05a','cl-6-basico','ma06-num','impropias-y-mixtos','Fracciones impropias y números mixtos','Transforma entre fracciones impropias y números mixtos.','Fundamental',35,9,'published',true),
('topic-ma06-oa05b','cl-6-basico','ma06-num','fracciones-en-la-recta','Fracciones y mixtos en la recta','Ubica fracciones y números mixtos en la recta numérica.','Fundamental',35,10,'published',true),
('topic-ma06-oa06a','cl-6-basico','ma06-num','suma-resta-fracciones','Suma y resta de fracciones','Opera fracciones con distintos denominadores usando equivalencias.','Fundamental',35,11,'published',true),
('topic-ma06-oa06b','cl-6-basico','ma06-num','suma-resta-numeros-mixtos','Suma y resta de números mixtos','Opera números mixtos interpretando unidades completas y partes fraccionarias.','Fundamental',35,12,'published',true),
('topic-ma06-oa07a','cl-6-basico','ma06-num','multiplicacion-decimales','Multiplicación de decimales','Multiplica decimales por naturales y múltiplos de 10 usando valor posicional.','Fundamental',35,13,'published',true),
('topic-ma06-oa07b','cl-6-basico','ma06-num','division-decimales','División de decimales','Divide decimales por naturales y relaciona el cálculo con reparto y medida.','Fundamental',35,14,'published',true),
('topic-ma06-oa08','cl-6-basico','ma06-num','problemas-fracciones-decimales-6b','Problemas con fracciones y decimales','Resuelve problemas rutinarios y no rutinarios seleccionando representaciones y operaciones.','Fundamental',35,15,'published',true),
('topic-ma06-oa09a','cl-6-basico','ma06-alg','patrones-en-tablas','Patrones en tablas','Descubre cómo cambian dos cantidades organizadas en una tabla.','Fundamental',35,16,'published',true),
('topic-ma06-oa09b','cl-6-basico','ma06-alg','reglas-de-formacion-6b','Reglas con lenguaje matemático','Formula una regla a partir de una tabla o situación.','Fundamental',35,17,'published',true),
('topic-ma06-oa10a','cl-6-basico','ma06-alg','expresiones-con-letras','Expresiones con letras','Usa letras para representar números variables o desconocidos.','Fundamental',35,18,'published',true),
('topic-ma06-oa10b','cl-6-basico','ma06-alg','modelar-relaciones-con-ecuaciones','Modelar relaciones con ecuaciones','Traduce situaciones a expresiones y ecuaciones sencillas.','Fundamental',35,19,'published',true),
('topic-ma06-oa11a','cl-6-basico','ma06-alg','ecuaciones-con-balanza','Ecuaciones como balanza','Comprende la igualdad manteniendo el equilibrio en ambos lados.','Fundamental',35,20,'published',true),
('topic-ma06-oa11b','cl-6-basico','ma06-alg','ecuaciones-procedimiento-formal','Resolver ecuaciones formalmente','Resuelve y comprueba ecuaciones de primer grado de una incógnita.','Fundamental',35,21,'published',true),
('topic-ma06-oa12a','cl-6-basico','ma06-geo','clasificacion-triangulos-6b','Clasificación de triángulos','Clasifica triángulos por lados y por ángulos.','Fundamental',35,22,'published',true),
('topic-ma06-oa12b','cl-6-basico','ma06-geo','construccion-triangulos','Construcción de triángulos','Construye triángulos a partir de medidas y analiza cuándo la construcción es posible.','Fundamental',35,23,'published',true),
('topic-ma06-oa13','cl-6-basico','ma06-geo','redes-de-cubos-paralelepipedos','Redes de cubos y paralelepípedos','Relaciona redes planas con las caras de cuerpos geométricos.','Fundamental',35,24,'published',true),
('topic-ma06-oa14','cl-6-basico','ma06-geo','teselaciones-transformaciones-6b','Teselaciones y transformaciones','Cubre el plano usando traslaciones, reflexiones y rotaciones.','Fundamental',35,25,'published',true),
('topic-ma06-oa15','cl-6-basico','ma06-geo','tipos-y-construccion-angulos','Tipos y construcción de ángulos','Reconoce y construye ángulos según su medida.','Fundamental',35,26,'published',true),
('topic-ma06-oa16','cl-6-basico','ma06-geo','angulos-opuestos-complementarios','Ángulos opuestos y complementarios','Identifica relaciones angulares al intersectar rectas.','Fundamental',35,27,'published',true),
('topic-ma06-oa17','cl-6-basico','ma06-geo','suma-angulos-interiores','Suma de ángulos interiores','Usa 180° en triángulos y 360° en cuadriláteros para razonar y calcular.','Fundamental',35,28,'published',true),
('topic-ma06-oa20','cl-6-basico','ma06-med','medicion-con-transportador','Medición con transportador','Estima, mide y construye ángulos expresados en grados.','Fundamental',35,29,'published',true),
('topic-ma06-oa21','cl-6-basico','ma06-med','angulos-paralelas-transversal','Ángulos en paralelas y transversal','Calcula ángulos usando relaciones entre paralelas, transversal y triángulos.','Fundamental',35,30,'published',true),
('topic-ma06-oa18','cl-6-basico','ma06-med','superficie-cubos-paralelepipedos','Superficie de cubos y paralelepípedos','Calcula el área total sumando áreas de caras.','Fundamental',35,31,'published',true),
('topic-ma06-oa19','cl-6-basico','ma06-med','volumen-cubos-paralelepipedos','Volumen de cubos y paralelepípedos','Calcula volumen como cantidad de unidades cúbicas.','Fundamental',35,32,'published',true),
('topic-ma06-oa22a','cl-6-basico','ma06-datos','diagramas-puntos-tallo-hojas-6b','Diagramas de puntos y tallo-hojas','Representa conjuntos de datos y reconoce su distribución.','Fundamental',35,33,'published',true),
('topic-ma06-oa22b','cl-6-basico','ma06-datos','comparar-distribuciones-6b','Comparar distribuciones','Compara centro, concentración y dispersión de dos grupos de datos.','Fundamental',35,34,'published',true),
('topic-ma06-oa23','cl-6-basico','ma06-datos','experimentos-repetidos-probabilidad','Experimentos aleatorios repetidos','Observa cómo las frecuencias se estabilizan al repetir un experimento.','Fundamental',35,35,'published',true),
('topic-ma06-oa24','cl-6-basico','ma06-datos','graficos-dobles-circulares','Gráficos de barra doble y circulares','Lee, compara e interpreta información en gráficos de barra doble y circulares.','Fundamental',35,36,'published',true)
