('school-6b-oa01a','school-6b-numeros-proporcionalidad','6b-factores-y-divisores','Factores y divisores','Encuentra todos los factores de un número y explica la relación con la división exacta.','Comprender y aplicar factores y divisores mediante representaciones, razonamiento y resolución de problemas.',50,'Básico',1,true,null,null,'{}'::text[],array['6 básico','factores y divisores']::text[],'{"course_id": "cl-6-basico", "topic_id": "topic-ma06-oa01a", "topic_slug": "factores-y-divisores"}'::jsonb),
('school-6b-oa01b','school-6b-numeros-proporcionalidad','6b-multiplos-mcm','Múltiplos y encuentros periódicos','Genera múltiplos y resuelve situaciones donde dos ciclos vuelven a coincidir.','Comprender y aplicar múltiplos y encuentros periódicos mediante representaciones, razonamiento y resolución de problemas.',50,'Básico',2,true,null,null,array['school-6b-oa01a']::text[],array['6 básico','múltiplos y encuentros periódicos']::text[],'{"course_id": "cl-6-basico", "topic_id": "topic-ma06-oa01b", "topic_slug": "multiplos-mcm"}'::jsonb),
('school-6b-oa01c','school-6b-numeros-proporcionalidad','6b-primos-y-compuestos','Números primos y compuestos','Distingue números primos y compuestos mediante sus factores.','Comprender y aplicar números primos y compuestos mediante representaciones, razonamiento y resolución de problemas.',50,'Básico',3,true,null,null,array['school-6b-oa01a']::text[],array['6 básico','números primos y compuestos']::text[],'{"course_id": "cl-6-basico", "topic_id": "topic-ma06-oa01c", "topic_slug": "primos-y-compuestos"}'::jsonb),
