('school-6b-oa04b','school-6b-numeros-proporcionalidad','6b-porcentaje-de-una-cantidad','Porcentaje de una cantidad','Calcula porcentajes frecuentes y resuelve problemas cotidianos.','Comprender y aplicar porcentaje de una cantidad mediante representaciones, razonamiento y resolución de problemas.',50,'Básico',8,true,null,null,array['school-6b-oa04a']::text[],array['6 básico','porcentaje de una cantidad']::text[],'{"course_id": "cl-6-basico", "topic_id": "topic-ma06-oa04b", "topic_slug": "porcentaje-de-una-cantidad"}'::jsonb),
