('school-6b-oa06b','school-6b-fracciones-decimales','6b-suma-resta-numeros-mixtos','Suma y resta de números mixtos','Opera números mixtos interpretando unidades completas y partes fraccionarias.','Comprender y aplicar suma y resta de números mixtos mediante representaciones, razonamiento y resolución de problemas.',50,'Básico',12,true,null,null,array['school-6b-oa06a']::text[],array['6 básico','suma y resta de números mixtos']::text[],'{"course_id": "cl-6-basico", "topic_id": "topic-ma06-oa06b", "topic_slug": "suma-resta-numeros-mixtos"}'::jsonb),
