('school-6b-oa09b','school-6b-algebra','6b-reglas-de-formacion-6b','Reglas con lenguaje matemático','Formula una regla a partir de una tabla o situación.','Comprender y aplicar reglas con lenguaje matemático mediante representaciones, razonamiento y resolución de problemas.',50,'Básico',17,true,null,null,array['school-6b-oa09a']::text[],array['6 básico','reglas con lenguaje matemático']::text[],'{"course_id": "cl-6-basico", "topic_id": "topic-ma06-oa09b", "topic_slug": "reglas-de-formacion-6b"}'::jsonb),
