('school-6b-oa12b','school-6b-geometria-angulos','6b-construccion-triangulos','Construcción de triángulos','Construye triángulos a partir de medidas y analiza cuándo la construcción es posible.','Comprender y aplicar construcción de triángulos mediante representaciones, razonamiento y resolución de problemas.',50,'Básico',23,true,null,null,array['school-6b-oa12a']::text[],array['6 básico','construcción de triángulos']::text[],'{"course_id": "cl-6-basico", "topic_id": "topic-ma06-oa12b", "topic_slug": "construccion-triangulos"}'::jsonb),
('school-6b-oa13','school-6b-geometria-angulos','6b-redes-de-cubos-paralelepipedos','Redes de cubos y paralelepípedos','Relaciona redes planas con las caras de cuerpos geométricos.','Comprender y aplicar redes de cubos y paralelepípedos mediante representaciones, razonamiento y resolución de problemas.',50,'Básico',24,true,null,null,'{}'::text[],array['6 básico','redes de cubos y paralelepípedos']::text[],'{"course_id": "cl-6-basico", "topic_id": "topic-ma06-oa13", "topic_slug": "redes-de-cubos-paralelepipedos"}'::jsonb),
