('school-6b-oa02','examples','Ejemplos resueltos','','{"examples": [{"title": "Ejemplo 1", "problem": "Un centro recibió 24 cajas con 7 cuadernos cada una y entregó 35. ¿Cuántos quedan?", "strategy": "Identifica los datos, representa la relación y comprueba el resultado.", "steps": ["Identifica qué se pregunta.", "Elige una representación o procedimiento.", "Resuelve y comprueba."], "answer": "133", "verification": "24×7=168; luego 168-35=133."}, {"title": "Ejemplo 2", "problem": "Un centro recibió 18 cajas con 9 cuadernos cada una y entregó 22. ¿Cuántos quedan?", "strategy": "Identifica los datos, representa la relación y comprueba el resultado.", "steps": ["Identifica qué se pregunta.", "Elige una representación o procedimiento.", "Resuelve y comprueba."], "answer": "140", "verification": "18×9=162; luego 162-22=140."}]}'::jsonb,6),
