('school-6b-oa22b','examples','Ejemplos resueltos','','{"examples": [{"title": "Ejemplo 1", "problem": "Grupo A: [5, 5, 6, 6, 7]. Grupo B: [5, 7, 9, 11, 13]. ¿Cuál tiene mayor dispersión?", "strategy": "Identifica los datos, representa la relación y comprueba el resultado.", "steps": ["Identifica qué se pregunta.", "Elige una representación o procedimiento.", "Resuelve y comprueba."], "answer": "Grupo B", "verification": "Mayor dispersión significa valores más separados."}, {"title": "Ejemplo 2", "problem": "Grupo A: [8, 9, 9, 10, 10]. Grupo B: [1, 9, 9, 10, 18]. ¿Cuál tiene mayor dispersión?", "strategy": "Identifica los datos, representa la relación y comprueba el resultado.", "steps": ["Identifica qué se pregunta.", "Elige una representación o procedimiento.", "Resuelve y comprueba."], "answer": "Grupo B", "verification": "Mayor dispersión significa valores más separados."}]}'::jsonb,6),
