('school-6b-oa23','examples','Ejemplos resueltos','','{"examples": [{"title": "Ejemplo 1", "problem": "Al lanzar una moneda equilibrada 20 veces y aumentar las repeticiones, ¿a qué proporción suele acercarse la frecuencia de caras?", "strategy": "Identifica los datos, representa la relación y comprueba el resultado.", "steps": ["Identifica qué se pregunta.", "Elige una representación o procedimiento.", "Resuelve y comprueba."], "answer": "Cerca de 1/2", "verification": "La frecuencia relativa tiende a acercarse a la probabilidad teórica 1/2."}, {"title": "Ejemplo 2", "problem": "Al lanzar una moneda equilibrada 30 veces y aumentar las repeticiones, ¿a qué proporción suele acercarse la frecuencia de caras?", "strategy": "Identifica los datos, representa la relación y comprueba el resultado.", "steps": ["Identifica qué se pregunta.", "Elige una representación o procedimiento.", "Resuelve y comprueba."], "answer": "Cerca de 1/2", "verification": "La frecuencia relativa tiende a acercarse a la probabilidad teórica 1/2."}]}'::jsonb,6),
